arguments.argument:
with(obj_unit)
{
if global.player_control=player and click_check=1
{
moni_go_waits=0
attack_waits=0
go_check=1
go_x=max(0, (mouse_x - other.x_loc)/other.xscale)
go_y=max(0, (mouse_y - other.y_loc)/other.yscale)

image_index=round(point_direction(x, y, go_x, go_y)/90)
sk_message_save(sk_get_o_space(), -1, 0, x, y, hp, go_check, go_x, go_y, attack_waits, attack_unit, moni_go_waits, moni_go_waits_id, image_index)
}
}
